<script lang="ts">
 import{onMount}from'svelte';import type{Contour,DesignOperation}from'@schubert/contracts';
 import{contourBounds,memorialContour,parseMillimetres,type MemorialShape}from'@schubert/geometry';import ShapePicker from'./ShapePicker.svelte';
 let{elementId,contour,onchange}:{elementId:string;contour:Contour;onchange:(operations:DesignOperation[])=>void}=$props();
 let shape:MemorialShape=$state('rectangle'),width=$state(''),height=$state(''),radius=$state(''),rise=$state(''),error=$state('');
 onMount(()=>{const b=contourBounds(contour);width=b.width;height=b.height;});
 function apply(){error='';try{const w=parseMillimetres(width),h=parseMillimetres(height);if(!w||!h)throw Error('Breite und Höhe vollständig in mm angeben.');const next=memorialContour(shape,w,h,{...(radius?{radiusMm:parseMillimetres(radius)??radius}:{}),...(rise?{archRiseMm:parseMillimetres(rise)??rise}:{})});onchange([{type:'set_contour',elementId,contour:next}]);}catch(problem){error=(problem as Error).message;}}
</script>
<details class="outline-presets"><summary>Grundform und Außenmaße ändern</summary><p>Wählen Sie eine neue bearbeitbare Grundform. Vorhandene Ausschnitte werden dabei ersetzt; Position, Material und Stärke bleiben bestehen. Mit „Rückgängig“ können Sie die Änderung zurücknehmen.</p><ShapePicker bind:value={shape}/><div class="pair"><label>Breite (mm)<input bind:value={width} inputmode="decimal"/></label><label>Höhe / Länge (mm)<input bind:value={height} inputmode="decimal"/></label></div>{#if shape==='rounded'}<label>Eckenradius (mm)<input bind:value={radius} inputmode="decimal" placeholder="Automatisch aus den Außenmaßen"/></label>{/if}{#if shape==='segment_arch'}<label>Bogenhöhe (mm)<input bind:value={rise} inputmode="decimal" placeholder="18 % der Breite"/></label>{/if}{#if error}<p class="error" role="alert">{error}</p>{/if}<button class="btn small primary" type="button" onclick={apply}>Grundform übernehmen</button></details>
<style>.outline-presets{padding:14px;background:var(--wash);border-radius:10px;margin-bottom:16px}.outline-presets summary{cursor:pointer;font-size:13px;font-weight:600;min-height:28px}.outline-presets p{font-size:12px;line-height:1.65;color:var(--muted);margin:12px 0}.pair{display:grid;grid-template-columns:1fr 1fr;gap:12px}label{display:block;font-size:12px;font-weight:500;margin:12px 0}input{display:block;width:100%;box-sizing:border-box;font:inherit;color:var(--ink);background:var(--paper);border:1px solid var(--line);border-radius:8px;min-height:44px;margin-top:6px;padding:10px}.outline-presets .error{color:var(--danger)}button{margin-top:8px}@media(max-width:720px){input{font-size:16px;min-height:48px}}</style>
